package audit

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/liubing0806/allowops/internal/store/db"
)

// This file is the audit package's database access layer. Fixed-shape
// statements are generated by sqlc (internal/store/queries/audit.sql) and are
// wrapped here to convert between the Go uint64/time.Time types and the bigint
// and timestamptz columns. Statements that return full event rows, and the
// dynamic partition DDL, are hand-written below. The d argument is any pgx
// executor: a pool, a dedicated pooled connection or a transaction.

const columns = `seq,at,subject_id,operation,resource,decision,reason,matched_rules,source_ip,hostname,action,job_id,task_id,policy_version,outputs,checkpoint_seq,checkpoint_hash,hash_input,prev_hash,hash`

var errBigintRange = errors.New("audit sequence outside the bigint range")

func toInt8(v uint64) (int64, error) {
	if v > math.MaxInt64 {
		return 0, errBigintRange
	}
	return int64(v), nil
}

func toUint8(v int64) (uint64, error) {
	if v < 0 {
		return 0, errBigintRange
	}
	return uint64(v), nil
}

func timestamptz(t time.Time) pgtype.Timestamptz { return pgtype.Timestamptz{Time: t, Valid: true} }

func optionalTimestamptz(t *time.Time) pgtype.Timestamptz {
	if t == nil {
		return pgtype.Timestamptz{}
	}
	return timestamptz(*t)
}

// optionalSeq converts the nullable bigint result of min/max, which sqlc types
// as interface{}, to the uint64 pointer used by callers.
func optionalSeq(v any) (*uint64, error) {
	switch n := v.(type) {
	case nil:
		return nil, nil
	case int64:
		u, err := toUint8(n)
		return &u, err
	default:
		return nil, fmt.Errorf("unexpected audit sequence type %T", v)
	}
}

// scan reads one columns row. Event rows are streamed by callers, so scanning
// stays outside sqlc: a malformed column is reported per row.
func scan(row pgx.Row) (Event, error) {
	var e Event
	var outputs []byte
	e.Version = 1
	err := row.Scan(&e.Seq, &e.At, &e.SubjectID, &e.Operation, &e.Resource, &e.Decision, &e.Reason, &e.MatchedRules, &e.SourceIP, &e.Hostname, &e.Action, &e.JobID, &e.TaskID, &e.PolicyVersion, &outputs, &e.CheckpointSeq, &e.CheckpointHash, &e.HashInput, &e.PrevHash, &e.Hash)
	if err != nil {
		var fieldError pgx.ScanArgError
		if errors.As(err, &fieldError) && e.Seq != 0 {
			return e, errMalformedEvent
		}
		return e, err
	}
	e.At = e.At.UTC()
	decoder := json.NewDecoder(bytes.NewReader(outputs))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&e.Outputs); err != nil {
		return e, errMalformedEvent
	}
	return e, nil
}

func eventsBetween(ctx context.Context, d db.DBTX, from, to uint64) (pgx.Rows, error) {
	return d.Query(ctx, "SELECT "+columns+" FROM audit_events WHERE seq>=$1 AND seq<=$2 ORDER BY seq,at", from, to)
}

func eventsFrom(ctx context.Context, d db.DBTX, next uint64, limit int) (pgx.Rows, error) {
	return d.Query(ctx, "SELECT "+columns+" FROM audit_events WHERE seq >= $1 ORDER BY seq,at LIMIT $2", next, limit)
}

type eventFilter struct {
	next, last                           uint64
	from, to                             *time.Time
	subject, hostname, action, job, oper string
	limit                                int
}

func eventsFiltered(ctx context.Context, d db.DBTX, f eventFilter) (pgx.Rows, error) {
	return d.Query(ctx, `SELECT `+columns+` FROM audit_events WHERE seq >= $1 AND seq <= $2 AND ($3::timestamptz IS NULL OR at >= $3) AND ($4::timestamptz IS NULL OR at < $4) AND ($5='' OR subject_id=$5) AND ($6='' OR hostname=$6) AND ($7='' OR action=$7) AND ($8='' OR job_id=$8) AND ($9='' OR operation=$9) ORDER BY seq,at LIMIT $10`, f.next, f.last, f.from, f.to, f.subject, f.hostname, f.action, f.job, f.oper, f.limit)
}

func lockXact(ctx context.Context, d db.DBTX, key int64) error {
	return db.New(d).LockAuditAdvisory(ctx, key)
}

func tryLock(ctx context.Context, d db.DBTX, key int64) (bool, error) {
	return db.New(d).TryLockAuditAdvisory(ctx, key)
}

func unlock(ctx context.Context, d db.DBTX, key int64) error {
	return db.New(d).UnlockAuditAdvisory(ctx, key)
}

func ping(ctx context.Context, d db.DBTX) error { return db.New(d).PingAuditSession(ctx) }

// currentBoundary returns the retained anchor row.
func currentBoundary(ctx context.Context, d db.DBTX) (uint64, []byte, error) {
	row, err := db.New(d).GetAuditBoundary(ctx)
	if err != nil {
		return 0, nil, err
	}
	seq, err := toUint8(row.Seq)
	return seq, row.Hash, err
}

// tip returns the newest event, or the retention boundary when no event remains.
func tip(ctx context.Context, d db.DBTX) (uint64, []byte, time.Time, error) {
	var at time.Time
	row, err := db.New(d).GetAuditTip(ctx)
	if errors.Is(err, pgx.ErrNoRows) {
		seq, hash, err := currentBoundary(ctx, d)
		return seq, hash, at, err
	}
	if err != nil {
		return 0, nil, at, err
	}
	seq, err := toUint8(row.Seq)
	return seq, row.Hash, row.At.Time, err
}

// lastCheckpointAt returns pgx.ErrNoRows when no checkpoint exists.
func lastCheckpointAt(ctx context.Context, d db.DBTX) (time.Time, error) {
	at, err := db.New(d).GetLastAuditCheckpointAt(ctx)
	return at.Time, err
}

func insertEvent(ctx context.Context, d db.DBTX, p Payload, outputs, input, previous, hash []byte) error {
	seq, err := toInt8(p.Seq)
	if err != nil {
		return err
	}
	policy, err := toInt8(p.PolicyVersion)
	if err != nil {
		return err
	}
	var checkpoint pgtype.Int8
	if p.CheckpointSeq != nil {
		if checkpoint.Int64, err = toInt8(*p.CheckpointSeq); err != nil {
			return err
		}
		checkpoint.Valid = true
	}
	return db.New(d).InsertAuditEvent(ctx, db.InsertAuditEventParams{
		Seq: seq, At: timestamptz(p.At), SubjectID: p.SubjectID, Operation: p.Operation, Resource: p.Resource,
		Decision: p.Decision, Reason: p.Reason, MatchedRules: p.MatchedRules, SourceIp: p.SourceIP, Hostname: p.Hostname,
		Action: p.Action, JobID: p.JobID, TaskID: p.TaskID, PolicyVersion: policy, Outputs: outputs,
		CheckpointSeq: checkpoint, CheckpointHash: p.CheckpointHash, HashInput: input, PrevHash: previous, Hash: hash,
	})
}

func maxSeq(ctx context.Context, d db.DBTX) (*uint64, error) {
	v, err := db.New(d).GetAuditMaxSeq(ctx)
	if err != nil {
		return nil, err
	}
	return optionalSeq(v)
}

func seqBounds(ctx context.Context, d db.DBTX, from, to *time.Time) (first, last *uint64, err error) {
	row, err := db.New(d).GetAuditSeqBounds(ctx, db.GetAuditSeqBoundsParams{FromAt: optionalTimestamptz(from), ToAt: optionalTimestamptz(to)})
	if err != nil {
		return nil, nil, err
	}
	if first, err = optionalSeq(row.Min); err != nil {
		return nil, nil, err
	}
	last, err = optionalSeq(row.Max)
	return first, last, err
}

func eventExists(ctx context.Context, d db.DBTX, seq uint64) (bool, error) {
	n, err := toInt8(seq)
	if err != nil {
		return false, err
	}
	return db.New(d).AuditEventExists(ctx, n)
}

// precedingHash returns the hash of event seq-1 or, when retention removed it,
// the boundary hash. It returns nil, nil when neither exists.
func precedingHash(ctx context.Context, d db.DBTX, seq uint64) ([]byte, error) {
	n, err := toInt8(seq)
	if err != nil {
		return nil, err
	}
	q := db.New(d)
	hash, err := q.GetAuditEventHash(ctx, n)
	if errors.Is(err, pgx.ErrNoRows) {
		hash, err = q.GetAuditBoundaryHash(ctx, n)
	}
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	return hash, err
}

// exportCursor returns pgx.ErrNoRows when the named cursor does not exist.
func exportCursor(ctx context.Context, d db.DBTX, name string) (uint64, []byte, error) {
	row, err := db.New(d).GetAuditExportCursor(ctx, name)
	if err != nil {
		return 0, nil, err
	}
	next, err := toUint8(row.NextSeq)
	return next, row.PrecedingHash, err
}

func insertExportCursor(ctx context.Context, d db.DBTX, name string, next uint64, anchor []byte) error {
	n, err := toInt8(next)
	if err != nil {
		return err
	}
	return db.New(d).InsertAuditExportCursor(ctx, db.InsertAuditExportCursorParams{Name: name, NextSeq: n, PrecedingHash: anchor})
}

func updateExportCursor(ctx context.Context, d db.DBTX, name string, next uint64, previous []byte) error {
	n, err := toInt8(next)
	if err != nil {
		return err
	}
	return db.New(d).UpdateAuditExportCursor(ctx, db.UpdateAuditExportCursorParams{Name: name, NextSeq: n, PrecedingHash: previous})
}

func createPartitions(ctx context.Context, d db.DBTX, first time.Time, months int) error {
	if months < math.MinInt32 || months > math.MaxInt32 {
		return errors.New("audit partition month count outside the integer range")
	}
	return db.New(d).CreateAuditPartitions(ctx, db.CreateAuditPartitionsParams{FirstMonth: timestamptz(first), Months: int32(months)})
}

// lastEventBefore returns nil when no event is older than cutoff.
func lastEventBefore(ctx context.Context, d db.DBTX, cutoff time.Time) (*Anchor, error) {
	row, err := db.New(d).GetAuditLastEventBefore(ctx, timestamptz(cutoff))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	seq, err := toUint8(row.Seq)
	return &Anchor{Seq: seq, Hash: row.Hash}, err
}

// retainedPrevHash returns pgx.ErrNoRows when event seq is not retained at or after cutoff.
func retainedPrevHash(ctx context.Context, d db.DBTX, seq uint64, cutoff time.Time) ([]byte, error) {
	n, err := toInt8(seq)
	if err != nil {
		return nil, err
	}
	return db.New(d).GetAuditRetainedPrevHash(ctx, db.GetAuditRetainedPrevHashParams{Seq: n, At: timestamptz(cutoff)})
}

func exportPending(ctx context.Context, d db.DBTX, seq uint64) (bool, error) {
	n, err := toInt8(seq)
	if err != nil {
		return false, err
	}
	return db.New(d).AuditExportPending(ctx, n)
}

func updateBoundary(ctx context.Context, d db.DBTX, a Anchor) error {
	n, err := toInt8(a.Seq)
	if err != nil {
		return err
	}
	return db.New(d).UpdateAuditBoundary(ctx, db.UpdateAuditBoundaryParams{Seq: n, Hash: a.Hash})
}

func expiredPartitions(ctx context.Context, d db.DBTX, cutoff time.Time) ([]string, error) {
	return db.New(d).ListExpiredAuditPartitions(ctx, timestamptz(cutoff))
}

// dropPartition is hand-written because a table name cannot be a bind parameter.
func dropPartition(ctx context.Context, d db.DBTX, name string) error {
	if _, err := d.Exec(ctx, "DROP TABLE "+pgx.Identifier{name}.Sanitize()); err != nil {
		return err
	}
	return db.New(d).DeleteAuditPartition(ctx, name)
}
